import { useMemo, useState } from 'react';
import { FlatList, Linking, StyleSheet, Text, TextInput, View } from 'react-native';

import { Tappable } from '@/components/tappable';
import { Colors, MaxContentWidth, Spacing } from '@/constants/theme';
import licenses from '@/data/licenses.json';

type Pkg = (typeof licenses.packages)[number];

/** Every npm package bundled with the app, with its license (generated by scripts/build-licenses.mjs). */
export default function LicensesScreen() {
  const [query, setQuery] = useState('');
  const [openId, setOpenId] = useState<string | null>(null);

  const data = useMemo(() => {
    const q = query.trim().toLowerCase();
    return q ? licenses.packages.filter((p) => p.n.toLowerCase().includes(q) || p.l.toLowerCase().includes(q)) : licenses.packages;
  }, [query]);

  return (
    <FlatList
      data={data}
      keyExtractor={(p) => `${p.n}@${p.v}`}
      contentContainerStyle={styles.list}
      keyboardShouldPersistTaps="handled"
      initialNumToRender={25}
      ListHeaderComponent={
        <View style={styles.header}>
          <Text style={styles.intro}>
            This app is built with open-source software. Thank you to everyone who made these packages.
          </Text>
          <TextInput
            value={query}
            onChangeText={setQuery}
            placeholder="Search packages or licenses"
            placeholderTextColor={Colors.textMuted}
            style={styles.search}
            autoCorrect={false}
            autoCapitalize="none"
            accessibilityLabel="Search packages or licenses"
          />
        </View>
      }
      renderItem={({ item }) => (
        <Row pkg={item} open={openId === `${item.n}@${item.v}`} onToggle={(id) => setOpenId((cur) => (cur === id ? null : id))} />
      )}
    />
  );
}

function Row({ pkg, open, onToggle }: { pkg: Pkg; open: boolean; onToggle: (id: string) => void }) {
  const id = `${pkg.n}@${pkg.v}`;
  const text = pkg.t >= 0 ? licenses.texts[pkg.t] : null;
  return (
    <Tappable onPress={() => onToggle(id)} style={styles.row} accessibilityHint="Shows the license text">
      <View style={styles.rowTop}>
        <Text style={styles.name} numberOfLines={1}>
          {pkg.n} <Text style={styles.version}>{pkg.v}</Text>
        </Text>
        <Text style={styles.license}>{pkg.l}</Text>
      </View>
      {open ? (
        <View style={styles.detail}>
          {pkg.r ? (
            <Text style={styles.link} onPress={() => Linking.openURL(pkg.r!)}>
              {pkg.r}
            </Text>
          ) : null}
          <Text style={styles.licenseText}>
            {text ?? `No license file is included in this package. Its declared license is ${pkg.l}; see its project page for details.`}
          </Text>
        </View>
      ) : null}
    </Tappable>
  );
}

const styles = StyleSheet.create({
  list: {
    width: '100%',
    maxWidth: MaxContentWidth,
    alignSelf: 'center',
    paddingHorizontal: Spacing.three,
    paddingBottom: Spacing.six,
  },
  header: { gap: Spacing.three, paddingTop: Spacing.two, paddingBottom: Spacing.two },
  intro: { color: Colors.textSecondary, fontSize: 14, lineHeight: 20 },
  search: {
    backgroundColor: Colors.surface,
    color: Colors.text,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: Colors.border,
    paddingHorizontal: Spacing.three,
    paddingVertical: 10,
    fontSize: 15,
  },
  row: {
    paddingVertical: 12,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: Colors.border,
  },
  rowTop: { flexDirection: 'row', justifyContent: 'space-between', gap: Spacing.two },
  name: { color: Colors.text, fontSize: 14, flexShrink: 1 },
  version: { color: Colors.textMuted, fontSize: 12 },
  license: { color: Colors.textMuted, fontSize: 12 },
  detail: { gap: Spacing.two, marginTop: Spacing.two },
  link: { color: Colors.text, fontSize: 13, textDecorationLine: 'underline' },
  licenseText: { color: Colors.textSecondary, fontSize: 11, lineHeight: 16, fontFamily: 'monospace' },
});
